1	// Red-first fixtures for this pack's checks: each rule is shown FIRING on a
2	// violating input and QUIET on a clean one. Dependency-free — run it with
3	//   node .claudinite/local/packs/vascular-coloring/pack.test.mjs
4	import assert from 'node:assert/strict';
5	
6	import overlayColorContrast from './overlay-color-contrast.mjs';
7	import renderedOverlaysUntracked from './rendered-overlays-untracked.mjs';
8	import panelScaleCalibration from './panel-scale-calibration.mjs';
9	import scaleNumbersMatchCalibration from './scale-numbers-match-calibration.mjs';
10	import lockedMetricFields from './locked-metric-fields.mjs';
11	import calibrationSingleSource from './calibration-single-source.mjs';
12	import renderOutputsGitignored from './render-outputs-gitignored.mjs';
13	
14	// The slice of the check context these rules use: file reads and the tracked list.
15	const ctx = ({ files = {}, tracked = [] }) => ({
16	  tracked,
17	  read: (p) => (p in files ? files[p] : null),
18	});
19	
20	const cases = [];
21	const test = (name, fn) => cases.push([name, fn]);
22	
23	// --- overlay-color-contrast -------------------------------------------------
24	
25	const OVERLAY = 'analysis/annotate_overlays.py';
26	
27	test('overlay-color-contrast fires on a red overlay colour', () => {
28	  const findings = overlayColorContrast.run(ctx({
29	    files: { [OVERLAY]: 'CAP_COL, ART_COL = (0, 200, 255), (255, 60, 30)\n' },
30	  }));
31	  assert.equal(findings.length, 1);
32	  assert.equal(findings[0].line, 1);
33	  assert.match(findings[0].what, /red-dominant/);
34	});
35	
36	test('overlay-color-contrast is quiet on the agreed palette', () => {
37	  const findings = overlayColorContrast.run(ctx({
38	    files: {
39	      [OVERLAY]: [
40	        '# an example artery gets a red arrow  <- prose, not a drawn colour',
41	        'CAP_COL, ART_COL, JUN_COL = (0, 200, 255), (40, 235, 90), (255, 0, 255)',
42	        'label = (255, 235, 60)',
43	        'white = (255, 255, 255)',
44	      ].join('\n'),
45	    },
46	  }));
47	  assert.deepEqual(findings, []);
48	});
49	
50	// --- rendered-overlays-untracked --------------------------------------------
51	
52	test('rendered-overlays-untracked fires on a committed overlay PNG', () => {
53	  const findings = renderedOverlaysUntracked.run(ctx({
54	    tracked: ['analysis/annotated/VESSEL_fig3_ischemic_gP-CD31_red.png', 'analysis/measure_vessels.py'],
55	  }));
56	  assert.equal(findings.length, 1);
57	  assert.match(findings[0].file, /^analysis\/annotated\//);
58	});
59	
60	test('rendered-overlays-untracked is quiet on scripts plus source images', () => {
61	  const findings = renderedOverlaysUntracked.run(ctx({
62	    tracked: [
63	      'analysis/measure_vessels.py',
64	      'analysis/results-first-pass.md',
65	      'references/wang-2022-cd31-vascular-network/figures/panels/VESSEL_fig3_ischemic_gP-CD31_red.png',
66	    ],
67	  }));
68	  assert.deepEqual(findings, []);
69	});
70	
71	// --- panel-scale-calibration -------------------------------------------------
72	
73	const MEASURE = 'analysis/measure_vessels.py';
74	const withTable = (keys, uncal = [], direct = []) =>
75	  `UM_PER_BAR = 50.0\nSCALEBAR_PX = {${keys.map((k) => `'${k}': 61`).join(', ')}}\n` +
76	  `UMPP_DIRECT = {\n${direct.map((k) => `    '${k}': 0.606,`).join('\n')}\n}\n` +
77	  `UNCALIBRATED = {\n${uncal.map((k) => `    '${k}': 'no bar drawn',`).join('\n')}\n}\n`;
78	
79	const PANELS = 'references/wang-2022-cd31-vascular-network/figures/panels';
80	
81	test('panel-scale-calibration fires on a panel with no bar measurement', () => {
82	  const findings = panelScaleCalibration.run(ctx({
83	    files: { [MEASURE]: withTable(['fig1']) },
84	    tracked: [
85	      `${PANELS}/VESSEL_fig1_C1_healthy_gP-CD31_red.png`,
86	      `${PANELS}/VESSEL_fig9_ischemic_gP-CD31_red.png`,
87	    ],
88	  }));
89	  assert.equal(findings.length, 1);
90	  assert.match(findings[0].what, /fig9/);
91	  assert.equal(findings[0].line, 2);
92	});
93	
94	test('panel-scale-calibration is quiet when every panel is calibrated', () => {
95	  const findings = panelScaleCalibration.run(ctx({
96	    files: { [MEASURE]: withTable(['fig1', 'fig3']) },
97	    tracked: [
98	      `${PANELS}/VESSEL_fig1_C1_healthy_gP-CD31_red.png`,
99	      `${PANELS}/VESSEL_fig3_ischemic_gP-CD31_red.png`,
100	      // fig7 has panels but no VESSEL_ panel — not in the working dataset.
101	      `${PANELS}/fig7_capillaries_gP-CD31.png`,
102	    ],
103	  }));
104	  assert.deepEqual(findings, []);
105	});
106	
107	test('panel-scale-calibration accepts a panel declared uncalibrated, with its reason', () => {
108	  const findings = panelScaleCalibration.run(ctx({
109	    files: { [MEASURE]: withTable(['fig1'], ['rust20fig2_overview']) },
110	    tracked: [
111	      `${PANELS}/VESSEL_fig1_C1_healthy_gP-CD31_red.png`,
112	      'references/rust-2020-fiji-vascular-analysis/figures/panels/VESSEL_rust20fig2_overview_intact_vasculature.png',
113	    ],
114	  }));
115	  assert.deepEqual(findings, []);
116	});
117	
118	test('panel-scale-calibration accepts a panel calibrated from its own image metadata', () => {
119	  const findings = panelScaleCalibration.run(ctx({
120	    files: { [MEASURE]: withTable(['fig1'], [], ['rust20suppl_representative']) },
121	    tracked: [
122	      'references/rust-2020-fiji-vascular-analysis/figures/panels/VESSEL_rust20suppl_representative.png',
123	    ],
124	  }));
125	  assert.deepEqual(findings, []);
126	});
127	
128	test('panel-scale-calibration still fires on a second paper\'s uncovered panel', () => {
129	  const findings = panelScaleCalibration.run(ctx({
130	    files: { [MEASURE]: withTable(['fig1'], ['rust20fig2_overview']) },
131	    tracked: [
132	      'references/rust-2020-fiji-vascular-analysis/figures/panels/VESSEL_rust20fig3_overview_AD_vasculature.png',
133	    ],
134	  }));
135	  assert.equal(findings.length, 1);
136	  assert.match(findings[0].what, /rust20fig3_overview_AD_vasculature/);
137	});
138	
139	// --- locked-metric-fields ----------------------------------------------------
140	
141	// A metrics dict shaped like the real one, minus whichever fields a case drops.
142	// Interleaved comments included deliberately: the real dict carries them, and a
143	// comment between two fields must not hide the field that follows it.
144	const metricsScript = (fields) => [
145	  '"""Delivers the professor\'s three asks per image:',
146	  '  - COUNT : number of branch segments (junction-to-junction pieces)',
147	  '"""',
148	  'ARTERY_DIAM_PX = 9.0',
149	  '',
150	  'def analyze(rgb, umpp):',
151	  '    m = dict(area=100 * mask.mean(),',
152	  '             # scale-invariant, comparable across figures:',
153	  `             ${fields.map((f) => `${f}=v_${f}`).join(', ')},`,
154	  '             wp90=round(float(np.percentile(widths, 90)), 1))',
155	  '    return m, dict(mask=mask, skel=skel)',
156	].join('\n');
157	
158	const ALL_LOCKED = ['segments', 'capillary', 'artery', 'length_um', 'length_density'];
159	
160	test('locked-metric-fields fires when the count unit stops being reported', () => {
161	  // COUNT re-pointed at connected components: `segments` is gone as a field and
162	  // survives only in the docstring — a text grep would be satisfied, the check
163	  // is not, because it reads the metrics dict.
164	  const findings = lockedMetricFields.run(ctx({
165	    files: {
166	      [MEASURE]: metricsScript(['vessels', 'capillary', 'artery', 'length_um', 'length_density']),
167	    },
168	  }));
169	  assert.equal(findings.length, 1);
170	  assert.match(findings[0].what, /COUNT is locked to branch segments/);
171	  assert.match(findings[0].what, /no segments field/);
172	  assert.equal(findings[0].line, 7);
173	});
174	
175	test('locked-metric-fields reports each locked ask that lost a field', () => {
176	  const findings = lockedMetricFields.run(ctx({
177	    files: { [MEASURE]: metricsScript(['segments', 'capillary', 'length_um']) },
178	  }));
179	  assert.deepEqual(findings.map((f) => f.what.split(' is locked')[0]), ['CATEGORIZE', 'MEASURE']);
180	  assert.match(findings[0].what, /no artery field/);
181	  assert.match(findings[1].what, /no length_density field/);
182	});
183	
184	test('locked-metric-fields is quiet when all three asks are still reported', () => {
185	  const findings = lockedMetricFields.run(ctx({ files: { [MEASURE]: metricsScript(ALL_LOCKED) } }));
186	  assert.deepEqual(findings, []);
187	});
188	
189	test('locked-metric-fields fires when the metrics dict itself is gone', () => {
190	  const findings = lockedMetricFields.run(ctx({
191	    files: { [MEASURE]: 'def analyze(rgb, umpp):\n    return defaultdict(list)\n' },
192	  }));
193	  assert.equal(findings.length, 1);
194	  assert.match(findings[0].what, /no metrics dict found/);
195	});
196	
197	// --- scale-numbers-match-calibration ----------------------------------------
198	
199	// The one calibration source: 50 um / bar width in px -> fig1 0.820, fig3 1.064.
200	const CALIB = "UM_PER_BAR = 50.0\nSCALEBAR_PX = {'fig1': 61, 'fig3': 47}\n";
201	const DOC = 'analysis/WORKING-GUIDE.md';
202	const RESULTS = 'analysis/results-first-pass.md';
203	const barTable = (barPx, umpp) => [
204	  '| figure(s) | 50 µm bar | **µm/px** | panel field of view |',
205	  '|---|---:|---:|---|',
206	  `| fig1 | ${barPx} px | **${umpp}** | ~301 µm |`,
207	  // A panel-level row in the same table: not a figure-level scale claim, so its
208	  // crop width and printed resolution are none of this rule's business.
209	  '| fig1 crop A2 | 380 px | **0.15** | as printed |',
210	].join('\n');
211	
212	test('scale-numbers-match-calibration fires on a stale µm/px quoted in prose', () => {
213	  const findings = scaleNumbersMatchCalibration.run(ctx({
214	    files: {
215	      [MEASURE]: CALIB,
216	      [DOC]: 'px→µm is calibrated from it (fig1 = 0.820, fig3 = 1.070 µm/px).\n',
217	    },
218	    tracked: [MEASURE, DOC],
219	  }));
220	  assert.equal(findings.length, 1);
221	  assert.equal(findings[0].file, DOC);
222	  assert.equal(findings[0].line, 1);
223	  assert.match(findings[0].what, /fig3.*1\.070.*1\.064/);
224	});
225	
226	test('scale-numbers-match-calibration fires on a stale bar width in a table column', () => {
227	  const findings = scaleNumbersMatchCalibration.run(ctx({
228	    files: { [MEASURE]: CALIB, [RESULTS]: `${barTable(59, '0.820')}\n` },
229	    tracked: [MEASURE, RESULTS],
230	  }));
231	  assert.equal(findings.length, 1);
232	  assert.equal(findings[0].line, 3);
233	  assert.match(findings[0].what, /scale bar is quoted as 59 px but SCALEBAR_PX says 61/);
234	});
235	
236	test('scale-numbers-match-calibration is quiet when every quoted number agrees', () => {
237	  const findings = scaleNumbersMatchCalibration.run(ctx({
238	    files: {
239	      [MEASURE]: CALIB,
240	      // Coarser precision is still the same number (0.82 == 50/61 to 2 dp);
241	      // the second paragraph assigns numbers to figures with no scale unit in
242	      // sight — a per-figure score is not a scale claim.
243	      [DOC]: 'calibrated from it (fig1 = 0.82, fig3 = 1.064 µm/px — SCALEBAR_PX).\n'
244	        + '\nRecall on the tuning sweep: fig1 = 0.35, fig3 = 0.41.\n',
245	      [RESULTS]: [
246	        barTable(61, '0.820'),
247	        '',
248	        // Per-panel metrics: decimals next to figure-prefixed panel names, in a
249	        // block that DOES say µm/px — a grep would cry wolf here, the
250	        // column-scoped parse must not (no µm/px or bar column in this table).
251	        'Lengths below are converted with each figure’s µm/px.',
252	        '| panel | len_um | len_dens | area% |',
253	        '|---|---:|---:|---:|',
254	        '| fig1_C1_healthy | 2145 | 23.6 | 14.2 |',
255	        '| fig3_ischemic | 2287 | 23.9 | 18.1 |',
256	      ].join('\n'),
257	    },
258	    tracked: [MEASURE, DOC, RESULTS],
259	  }));
260	  assert.deepEqual(findings, []);
261	});
262	
263	// --- calibration-single-source ----------------------------------------------
264	
265	const ANNOTATE = 'analysis/annotate_overlays.py';
266	const CALIB_SRC = [
267	  '"""Vessel quantification.',
268	  '',
269	  "Calibration lives here: SCALEBAR_PX = {'fig1': 61} — a docstring quoting the",
270	  'table documents it, it does not define it.',
271	  '"""',
272	  'import os',
273	  'UM_PER_BAR = 50.0',
274	  "SCALEBAR_PX = {'fig1': 61, 'fig3': 47}",
275	].join('\n');
276	
277	test('calibration-single-source fires on a second calibration table in another script', () => {
278	  const findings = calibrationSingleSource.run(ctx({
279	    files: {
280	      [MEASURE]: CALIB_SRC,
281	      // The importing script grows its own copy — the drift the rule is about.
282	      [ANNOTATE]: [
283	        'from measure_vessels import (segment, prune, umpp_for,',
284	        '                             ARTERY_DIAM_PX, SRC)',
285	        '',
286	        "SCALEBAR_PX = {'fig1': 61, 'fig3': 47, 'fig4': 76}",
287	      ].join('\n'),
288	    },
289	    tracked: [MEASURE, ANNOTATE],
290	  }));
291	  assert.equal(findings.length, 1);
292	  assert.equal(findings[0].file, ANNOTATE);
293	  assert.equal(findings[0].line, 4);
294	  assert.match(findings[0].what, /defines its own SCALEBAR_PX/);
295	});
296	
297	test('calibration-single-source fires when the source assigns one name twice', () => {
298	  const findings = calibrationSingleSource.run(ctx({
299	    files: { [MEASURE]: `${CALIB_SRC}\n\n# re-measured fig3, old table left above\nSCALEBAR_PX = {'fig1': 61, 'fig3': 44}\n` },
300	    tracked: [MEASURE],
301	  }));
302	  assert.equal(findings.length, 1);
303	  assert.match(findings[0].what, /SCALEBAR_PX is assigned 2 times/);
304	  assert.equal(findings[0].line, 11);
305	});
306	
307	test('calibration-single-source is quiet when the table is defined once and imported', () => {
308	  const findings = calibrationSingleSource.run(ctx({
309	    files: {
310	      [MEASURE]: CALIB_SRC,
311	      // An import of the name, a continuation line carrying it, and a keyword
312	      // argument spelled like an assignment — none of them a definition.
313	      [ANNOTATE]: [
314	        'from measure_vessels import (segment, prune, umpp_for,',
315	        '                             ARTERY_DIAM_PX, SCALEBAR_PX, SRC)',
316	        '',
317	        'bar = draw_bar(img,',
318	        '               UM_PER_BAR=50.0)',
319	        "# SCALEBAR_PX = {'fig1': 61}   <- kept as a comment while debugging",
320	      ].join('\n'),
321	    },
322	    tracked: [MEASURE, ANNOTATE, 'analysis/WORKING-GUIDE.md'],
323	  }));
324	  assert.deepEqual(findings, []);
325	});
326	
327	// --- render-outputs-gitignored ----------------------------------------------
328	
329	const script = (dir) => [
330	  '#!/usr/bin/env python3',
331	  '"""Writes PNGs to analysis/reports/ (gitignored)."""',
332	  'import os',
333	  'HERE = os.path.dirname(os.path.abspath(__file__))',
334	  `OUT = os.path.join(HERE, '${dir}')`,
335	  "SRC = os.path.normpath(os.path.join(HERE, '..', 'references'))",
336	  '',
337	  'def main():',
338	  '    os.makedirs(OUT, exist_ok=True)',
339	  "    canvas.save(os.path.join(OUT, name + '.png'))",
340	].join('\n');
341	
342	const GITIGNORE = ['# generated overlays', '/analysis/overlays/', '/analysis/annotated/', '__pycache__/'].join('\n');
343	
344	test('render-outputs-gitignored fires on a new output directory nobody ignored', () => {
345	  const findings = renderOutputsGitignored.run(ctx({
346	    files: { [ANNOTATE]: script('reports'), '.gitignore': GITIGNORE },
347	    tracked: [ANNOTATE, '.gitignore'],
348	  }));
349	  assert.equal(findings.length, 1);
350	  assert.equal(findings[0].file, ANNOTATE);
351	  assert.equal(findings[0].line, 9);
352	  assert.match(findings[0].what, /analysis\/reports\/, which no .gitignore entry covers/);
353	});
354	
355	test('render-outputs-gitignored fires when an entry is un-ignored by a later negation', () => {
356	  const findings = renderOutputsGitignored.run(ctx({
357	    files: {
358	      [ANNOTATE]: script('annotated'),
359	      '.gitignore': `${GITIGNORE}\n!/analysis/annotated/\n`,
360	    },
361	    tracked: [ANNOTATE, '.gitignore'],
362	  }));
363	  assert.equal(findings.length, 1);
364	  assert.match(findings[0].what, /analysis\/annotated\//);
365	});
