48	
49	// What a session may claim, and what each one means for the item. `record` is the
50	// execution-record status, and `null` means no record: an approval park is a run
51	// that SUCCEEDED and left a PR, which the record vocabulary has no word for, and
52	// a fifth status would be stored data every decoder in the fleet must learn.
53	export const OUTCOMES = Object.freeze({
54	  done: { label: TASK_DONE, closes: true, stateReason: 'completed', record: 'success' },
55	  approval: { label: NEEDS_HUMAN_APPROVAL, closes: false, record: null },
56	  action: { label: NEEDS_HUMAN_ACTION, closes: false, record: 'failed' },
57	  decision: { label: NEEDS_HUMAN_DECISION, closes: false, record: 'failed' },
58	  failure: { label: NEEDS_HUMAN_FAILURE, closes: false, record: 'failed' },
59	});
