61	export function parseArgs(argv) {
62	  const args = {};
63	  for (let n = 0; n < argv.length; n += 1) {
64	    const m = /^--([a-z-]+)$/.exec(argv[n]);
65	    if (m) { args[m[1]] = argv[n + 1] ?? ''; n += 1; }
66	  }
67	  const issue = Number(args.issue);
68	  if (!Number.isInteger(issue) || issue <= 0) return { error: '--issue must be the work item\'s issue number' };
69	  if (!OUTCOMES[args.outcome]) {
70	    return { error: `--outcome must be one of ${Object.keys(OUTCOMES).join(', ')}, got ${JSON.stringify(args.outcome ?? null)}` };
71	  }
72	  if (!String(args.summary ?? '').trim()) return { error: '--summary must say what happened; it is the item\'s only durable account' };
73	  if (args.outcome === 'approval' && !args.pr) {
74	    return { error: '--pr must name the pull request an approval park is waiting on — a park nobody can act on is not a park' };
75	  }
76	  return {
77	    issue, outcome: args.outcome, summary: args.summary, pr: args.pr ? Number(args.pr) : null,
78	    repo: args.repo || null, itemFile: args['item-file'] || null,
