82	// Why an item may NOT be converged by this call. Refusing loudly beats writing a
83	// terminal state onto the wrong issue: this runs from a session, whose whole
84	// notion of which item it holds came from an untrusted fire payload.
85	export function refusal(item, issue) {
86	  if (!item) return `#${issue} could not be read`;
87	  // A marked issue IS its own item (PRINCIPLES.md), so the title test cannot be the
88	  // membership test any more: what says this is one is the machine block adoption
89	  // wrote — never the body's first line, which on a marked issue is a person's prose.
90	  //
91	  // THREE SIGNALS, ANY ONE SUFFICIENT. A membership test gated on the single artifact
92	  // it exists to validate refuses exactly the items that artifact is missing from: an
93	  // issue adopted before the block delimiters existed carries its fields bare, and was
94	  // refused here into a by-hand convergence that dropped half the transition
95	  // (missingbulb/Shepherd#360). The origin label is the independent one — carried for
96	  // life, and platform-write-gated like the block was.
97	  const marked = ORIGIN_LABELS.some((name) => hasLabel(item, name));
98	  if (!parseWorkItemTitle(item.title ?? '') && machineBlockOf(item.body ?? '') === null && !marked) {
99	    return `#${issue} is not a Claudinite work item`;
100	  }
101	  if (item.state !== 'open') return `#${issue} is already closed — it was converged once already`;
102	  if (!isStatus(item, STATUS_RUNNING_AGENT)) {
103	    return `#${issue} is not with an agent (\`${AGENT}\`) — this session does not hold it, so it is not this session's to converge`;
104	  }
105	  return null;
106	}
