108	// The record line for this item, or null where the vocabulary has no true answer.
109	export const recordLine = (item, status) => {
110	  const parsed = parseWorkItemTitle(item.title);
111	  return status && parsed
112	    ? renderTaskExec({ pack: parsed.pack, task: parsed.task, slotId: `#${item.number}`, status })
113	    : null;
114	};
