116	// The comment one converge writes: the session's account, then the record, so a
117	// reader and a parser both find what they came for in one place.
118	// THE EPISODE ENDS WHERE THE ITEM IS LET GO OF (F18/F24). An executor that parks
119	// an item strikes its own claim on the way out; a SESSION cannot — its claim is
120	// the executor's, and it has no edit for it — so the boundary rides its own
121	// comment instead. `claimWinner` reads the last comment carrying the marker
122	// whatever wrote it, so this is the same mechanism, not a second one.
123	//
124	// Without it every claim from the parked episode outlives the park: a person
125	// re-queues the item, the next executor claims it, and `claimWinner` hands the
126	// episode to the dead claim that is still the earliest one on the issue. The item
127	// then loses every race it will ever have — which is the livelock F18 describes,
128	// reached through the one converge that had no way to say it had let go.
129	export function convergeComment(item, { summary, pr, record, boundary = false }) {
130	  const rec = recordLine(item, record);
131	  const line = rec ? `\n\n\`\`\`\n${rec}\n\`\`\`` : '';
132	  const waiting = pr ? `\n\nWaiting on a person: merge or close #${pr}, then close this item.` : '';
133	  const ends = boundary
134	    ? `\n\n${EPISODE_MARKER}\nThis session released the item without closing it; every claim before this line is spent.`
135	    : '';
136	  return `${summary.trim()}${waiting}${line}${ends}`;
137	}
