139	// THE TRANSITION AS DATA (#1374). The side effects were a straight line of
140	// `await api.…` calls, which silently made REST the only way to perform them —
141	// and the sessions `invoke.mjs` hands work to have no REST route to their own
142	// repository, so the last step of every agentic run was the one step that
143	// environment could not take.
144	//
145	// So the sequence is planned as OPS and executed by whoever can. The planner is
146	// the single source of what a convergence IS; the executors differ only in
147	// transport. The session still supplies nothing but the judgment.
148	//
149	// Removes are granular and unconditional — every spelling of the status being
150	// left, not only the ones this snapshot shows (apply-status.mjs's rule: a member's
151	// items outlive its converges, so an item may wear an older engine's spelling).
152	export function convergeOps(item, plan) {
153	  const spec = OUTCOMES[plan.outcome];
154	  // A park leaves the item open for somebody else to claim, so its comment carries
155	  // the episode boundary; a close needs none — nothing re-claims a closed item.
156	  const ops = [{ kind: 'comment', issue: item.number, body: convergeComment(item, { ...plan, record: spec.record, boundary: !spec.closes }) }];
157	
158	  // The record goes to BOTH sinks, and neither is redundant: the comment above is
159	  // the durable one (Actions logs expire, the item does not), while this printed
160	  // copy lands in the session transcript, which is what the usage fold reads for
161	  // the task-status census.
162	  const rec = recordLine(item, spec.record);
163	  if (rec) ops.push({ kind: 'record', line: rec });
164	
165	  for (const label of spellingsOf(STATUS_RUNNING_AGENT)) {
166	    ops.push({ kind: 'removeLabel', issue: item.number, name: label });
167	  }
168	  // ONE label, on both paths: the outcome IS the status. A park in particular is
169	  // never a pair, so nothing can be half-applied (#1385).
170	  ops.push({ kind: 'addLabel', issue: item.number, name: spec.label });
171	
172	  // THE PARK'S END CONDITION (#1468). The comment above already tells a person to
173	  // merge or close the pull request; this says the same thing where the janitor can
174	  // read it, so the item ends when that happens instead of waiting for someone to
175	  // notice it already did. Every park that names one gets it, not only `approval`.
176	  if (!spec.closes && plan.pr) {
177	    ops.push({ kind: 'setBody', issue: item.number, body: editItemBody(item.body, (m) => withEndsWhen(m, plan.pr)) });
178	  }
179	
180	  // SUPERSEDING (PRINCIPLES.md). The executor decided at resolution which of this
181	  // task's earlier pull requests a `supersede_existing_pr` run replaces and stamped
182	  // them on the item; they close only once THIS run's own pull request exists — a
183	  // run that delivered nothing, or broke, leaves them where they were, so a review
184	  // member's pending pull request is never taken away for nothing.
185	  const { supersedes } = parseWorkItemBody(item.body ?? '');
186	  if (plan.pr && (plan.outcome === 'done' || plan.outcome === 'approval')) {
187	    for (const number of supersedes) {
188	      ops.push({ kind: 'closePull', number, successor: plan.pr, body: `Superseded by #${plan.pr}, a later run of the same task. Closing this one.` });
189	    }
190	  }
191	
192	  if (spec.closes) {
193	    // A DONE TERMINAL CLOSES THE ISSUE IT STANDS ON, marked or filed (#1489,
194	    // reversing docs/PRINCIPLES.md's "never a marked issue"). `done` is the one outcome
195	    // that means nothing is left for anyone to act on, so an issue left open under
196	    // it asks its author to come and agree with what the run already settled. Every
197	    // other outcome parks, and a park leaves the issue open to be waited on.
198	    ops.push({ kind: 'close', issue: item.number, stateReason: spec.stateReason });
199	    return ops;
200	  }
201	
202	  // A REQUEST ITEM WRITES BACK TO ITS ISSUE, on the one end that is its business
203	  // (PRINCIPLES.md). Only the approval park: a failure deliberately writes nothing and
204	  // leaves `claude-queued` standing, because re-arming work that writes code is a
205	  // person's decision and that standing label is what stops the next scheduler run
206	  // queueing a second run of the same request. Only a LEGACY shadow item writes
207	  // back to a different issue.
208	  const { request } = parseWorkItemBody(item.body ?? '');
209	  if (request && request !== item.number && plan.outcome === 'approval') {
210	    ops.push({ kind: 'comment', issue: request, body: `A pull request for this is open and waiting on you: #${plan.pr}. Merge or close it.` });
