217	// THE SESSION EXECUTOR'S SCRIPT. Same ops, addressed to the GitHub tools a session
218	// does have. Two differences forced by that surface, both handled here rather than
219	// left to the session to work out:
220	//
221	//  - THERE IS NO GRANULAR LABEL WRITE. `issue_write` replaces the whole set, so the
222	//    granular removes and adds are folded into the FINAL set here, computed from the
223	//    labels this item was read with. Everything not a status label is carried through.
224	//  - THE RECORD IS PRINTED BY THE SESSION, which is where it has to be anyway: the
225	//    usage fold reads the census out of the session transcript.
226	export function sessionScript(item, plan, repo) {
227	  const [owner, name] = String(repo).split('/');
228	  const lines = [];
229	  let n = 0;
230	  const step = (s) => { n += 1; lines.push(`${n}. ${s}`); };
231	
232	  // The item's own label set can be computed exactly, because the item was read
233	  // with its labels. Any OTHER issue's cannot — so that one is emitted as a
234	  // read-modify-write naming only the change, and never as a computed set, which
235	  // would silently drop every label this process never saw.
236	  const own = new Set(labelNames(item));
237	  const foreign = [];
238	  // The body write folds into the item's own `issue_write`, which is one call
239	  // either way. A park never closes, so the step it folds into is the trailing
240	  // label write below.
241	  let newBody = null;
242	
243	  for (const op of convergeOps(item, plan)) {
244	    if (op.kind === 'comment') {
245	      step(`\`add_issue_comment\` — owner \`${owner}\`, repo \`${name}\`, issue_number \`${op.issue}\`, body exactly:\n\n<<<BODY\n${op.body}\n>>>END\n`);
246	    } else if (op.kind === 'record') {
247	      step(`Output this line, on its own, in your reply. Nothing else emits it, and the usage census is read from your transcript:\n\n    ${op.line}\n`);
248	    } else if (op.kind === 'removeLabel' || op.kind === 'addLabel') {
249	      if (op.issue === item.number) {
250	        if (op.kind === 'removeLabel') own.delete(op.name); else own.add(op.name);
251	      } else {
252	        foreign.push(op);
253	      }
254	    } else if (op.kind === 'setBody' && op.issue === item.number) {
255	      newBody = op.body;
256	    } else if (op.kind === 'close') {
257	      step(`\`issue_write\` — method \`update\`, owner \`${owner}\`, repo \`${name}\`, issue_number \`${op.issue}\`,`
258	        + ` labels \`${JSON.stringify([...own])}\`, state \`closed\`, state_reason \`${op.stateReason}\``);
259	      own.clear();
260	    } else if (op.kind === 'closePull') {
261	      step(`\`add_issue_comment\` — owner \`${owner}\`, repo \`${name}\`, issue_number \`${op.number}\` (a pull request), body exactly:\n\n<<<BODY\n${op.body}\n>>>END\n`);
262	      step(`\`update_pull_request\` — owner \`${owner}\`, repo \`${name}\`, pullNumber \`${op.number}\`, state \`closed\``);
263	    }
264	  }
265	  // A park never closed, so its label write is still owed.
266	  if (own.size) {
267	    step(`\`issue_write\` — method \`update\`, owner \`${owner}\`, repo \`${name}\`, issue_number \`${item.number}\`,`
268	      + ` labels \`${JSON.stringify([...own])}\``
269	      + (newBody === null ? '' : `, body exactly:\n\n<<<BODY\n${newBody}\n>>>END\n`));
270	  }
271	  for (const op of foreign) {
272	    step(`On #${op.issue}: ${op.kind === 'addLabel' ? 'ADD' : 'REMOVE'} the label \`${op.name}\`.`
273	      + ` Read that issue's current labels first and write them back with only this one change —`
274	      + ` \`issue_write\` replaces the whole set, and this process never saw the rest.`);
275	  }
276	  return lines.join('\n');
277	}
278	
279	async function main() {
280	  const plan = parseArgs(process.argv.slice(2));
281	  if (plan.error) {
282	    console.error(`converge-item: ${plan.error}`);
283	    process.exit(2);
284	  }
285	
286	  // The repo this item lives in. `--repo` is what instructions.md passes; the two
287	  // environment names answer for a session whose harness sets one of them.
288	  const repo = plan.repo ?? actionsEnv().CLAUDINITE_ITEM_REPO ?? actionsEnv().GITHUB_REPOSITORY ?? null;
289	  if (!repo) {
290	    console.error('converge-item: --repo <owner/name> names the repository this item lives in');
291	    process.exit(2);
292	  }
293	
294	  // THE ITEM IS HANDED IN. This process cannot read it — that is the whole premise
295	  // of the file — so the session reads it with its own tools and passes it through.
296	  // A file rather than an argument: an item's body is prose of arbitrary length, and
297	  // a shell-quoted one is a quoting bug waiting for the first apostrophe.
298	  // `CLAUDINITE_ITEM_JSON` stays readable for a member whose instructions.md is a
299	  // cycle behind, since a mount updates on its own schedule.
300	  const raw = plan.itemFile
301	    ? await readFile(plan.itemFile, 'utf8')
302	    : (actionsEnv().CLAUDINITE_ITEM_JSON ?? '');
303	  let item = null;
304	  try { item = JSON.parse(raw || 'null'); } catch { item = null; }
305	  if (!item) {
306	    console.error('converge-item: --item-file must hold the issue as your GitHub tools returned it'
307	      + ' (number, title, body, state, labels).\n'
308	      + `Read it first: \`issue_read\` method \`get\` on ${repo} #${plan.issue}, save the JSON, pass the path.`);
309	    process.exit(2);
310	  }
311	
312	  const no = refusal(item, plan.issue);
313	  if (no) { console.error(`converge-item: ${no}`); process.exit(1); }
314	
315	  // The successful outcome. Everything below is the transition, decided here and
316	  // performed by the session — so it goes to stdout and the process exits clean.
317	  console.log('converge-item: the transition below is yours to execute.\n'
318	    + 'Make these calls with your GitHub tools, in this order, changing nothing. Then stop.\n');
319	  console.log(sessionScript(item, plan, repo));
320	}
321	
322	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
323	  main().catch((e) => { console.error(e); process.exit(1); });
324	}
